/** Helpers for Google's string encodings of time. All return null instead of throwing. */
object GoogleTime {
    /** Parses an RFC 3339 timestamp such as `2026-11-10T22:15:00Z` or `...+01:00` or with fractional seconds. */
    fun parseInstant(value: String?): Instant? {
        if (value.isNullOrBlank()) return null
        return try {
            java.time.OffsetDateTime.parse(value).toInstant()
        } catch (_: DateTimeParseException) {
            try { Instant.parse(value) } catch (_: DateTimeParseException) { null }
        }
    }

    /** Parses a `google-duration` such as `"3600s"`, `"-18000s"` or `"0.5s"` to milliseconds. */
    fun durationMillis(value: String?): Long? {
        val text = value?.trim() ?: return null
        if (!text.endsWith("s")) return null
        val seconds = text.dropLast(1).toBigDecimalOrNull() ?: return null
        return seconds.movePointRight(3).toLong()
    }

    /** Offset of the local time from UTC, in whole seconds (e.g. `"-18000s"` gives -18000). */
    fun offsetSeconds(value: String?): Int? = durationMillis(value)?.div(1000L)?.toInt()

    /** Converts a calendar [GhDate] to ISO `YYYY-MM-DD`, or null if year, month or day is missing. */
    fun isoDate(date: GhDate?): String? {
        val y = date?.year ?: return null
        val m = date.month ?: return null
        val d = date.day ?: return null
        if (y < 1 || m !in 1..12 || d !in 1..31) return null
        return String.format(java.util.Locale.ROOT, "%04d-%02d-%02d", y, m, d)
    }
}
